class DSU:
    def __init__(self, n):
        self.parent = list(range(n + 1))
        self.rank = [0] * (n + 1)
        self.components = n
    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]
    def union(self, x, y):
        xr, yr = self.find(x), self.find(y)
        if xr == yr:
            return False
        if self.rank[xr] < self.rank[yr]:
            self.parent[xr] = yr
        else:
            self.parent[yr] = xr
            if self.rank[xr] == self.rank[yr]:
                self.rank[xr] += 1
        self.components -= 1
        return True

def maxNumEdgesToRemove(n, edges):
    alice = DSU(n)
    bob = DSU(n)
    res = 0
    # Type 3: shared edges first
    for t, u, v in edges:
        if t == 3:
            shared = alice.union(u, v) | bob.union(u, v)
            if not shared:
                res += 1
    # Type 1: Alice-only
    for t, u, v in edges:
        if t == 1:
            if not alice.union(u, v):
                res += 1
    # Type 2: Bob-only
    for t, u, v in edges:
        if t == 2:
            if not bob.union(u, v):
                res += 1
    if alice.components > 1 or bob.components > 1:
        return -1
    return res
